const fs=require('fs');
const [,,srcPath,outPath]=process.argv;
if(!srcPath||!outPath) throw new Error('USAGE: node patch-card-signal-more-20261004.js <src> <out>');
let s=fs.readFileSync(srcPath,'utf8');
const MARK='B46_CARD_SIGNAL_MORE_COMPACT_20261004';
const OLD_INLINE=`function inlineSignalsHtml(rows){if(!Array.isArray(rows)||!rows.length)return '';return \`<div class="signal-inline-stack" data-inline-signal-count="\${rows.length}" style="min-width:0;display:grid;gap:6px">\${rows.map(inlineSignalHtml).join('')}</div>\`}`;
const NEW_INLINE=`/* ${MARK}: keep match cards height-stable by showing only the first signal inline; +More stays on the same line and full signal detail remains in Featured/Expanded. */\nfunction inlineSignalsHtml(rows){if(!Array.isArray(rows)||!rows.length)return '';return \`<div class="signal-inline-stack" data-inline-signal-count="\${rows.length}" style="min-width:0;display:grid;gap:6px">\${inlineSignalHtml(rows[0],rows.length>1)}</div>\`}`;
const OLD_SIG='function inlineSignalHtml(s){';
const NEW_SIG='function inlineSignalHtml(s,hasMore=false){';
const OLD_RETURN='  return `<div class="signal-cell locked prediction-live"><span class="pred-main">${esc(market)} · ${esc(pick)}</span><span class="pred-sub">${odds===null?\'LIVE\':`@ ${odds.toFixed(2)}`}</span></div>`;';
const NEW_RETURN='  const sub=odds===null?\'LIVE\':`@ ${odds.toFixed(2)}`;\n  return `<div class="signal-cell locked prediction-live"><span class="pred-main">${esc(market)} · ${esc(pick)}</span><span class="pred-sub">${esc(sub)}${hasMore?\' · +More\':\'\'}</span></div>`;';
if(s.includes(MARK)) throw new Error('CARD_SIGNAL_MORE_ALREADY_PRESENT_STOP');
if(!s.includes('B46_STABLE_MATCH_CARD_DOM_20261004')) throw new Error('STABLE_CARD_DOM_BASE_MISSING_STOP');
if(!s.includes('B46_CARD_SIGNAL_COUNT_COLLISION_FIX_20261004')) throw new Error('SIGNAL_COUNT_COLLISION_FIX_BASE_MISSING_STOP');
if((s.split(OLD_INLINE).length-1)!==1) throw new Error('INLINE_SIGNALS_ANCHOR_NOT_EXACTLY_ONE');
if((s.split(OLD_SIG).length-1)!==1) throw new Error('INLINE_SIGNAL_FUNCTION_ANCHOR_NOT_EXACTLY_ONE');
if((s.split(OLD_RETURN).length-1)!==1) throw new Error('INLINE_SIGNAL_RETURN_ANCHOR_NOT_EXACTLY_ONE');
if(!s.includes("const signal=$('[data-featured-signal]'),sigs=visibleSignalsFor(f),hasSignals=sigs.length>0,signalHtml=sigs.map")) throw new Error('FEATURED_FULL_SIGNAL_LIST_ANCHOR_MISSING');
s=s.replace(OLD_INLINE,NEW_INLINE).replace(OLD_SIG,NEW_SIG).replace(OLD_RETURN,NEW_RETURN);
if(!s.includes(MARK)) throw new Error('CARD_SIGNAL_MORE_PATCH_MISSING');
if(s.includes('rows.map(inlineSignalHtml).join')) throw new Error('INLINE_ALL_SIGNAL_RENDER_STILL_PRESENT');
if(!s.includes('inlineSignalHtml(rows[0],rows.length>1)')) throw new Error('FIRST_SIGNAL_PLUS_MORE_RENDER_MISSING');
if(!s.includes("hasMore?' · +More':''")) throw new Error('PLUS_MORE_LABEL_MISSING');
if(!s.includes("signalHtml=sigs.map")) throw new Error('FEATURED_FULL_SIGNAL_LIST_CHANGED');
fs.writeFileSync(outPath,s);
console.log(JSON.stringify({ok:true,marker:MARK,inputBytes:Buffer.byteLength(fs.readFileSync(srcPath)),outputBytes:Buffer.byteLength(s),fetchCountBefore:(fs.readFileSync(srcPath,'utf8').match(/\bfetch\(/g)||[]).length,fetchCountAfter:(s.match(/\bfetch\(/g)||[]).length}));
